// Jira Cloud on an API token: every operation of the Jira platform REST API and of Jira Software (boards, sprints,
// epics, backlog). actions.json is generated by `bun scripts/openapi-actions.ts jira`. The person pastes their site,
// email and API token in one line; calls go to their own site with basic auth. Triggers: polls/jira.ts, plus a webhook
// for what a list can't show (triggers.ts). COVERAGE.md says what's where.
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

export type Login = { site: string; email: string; token: string };

// "yourcompany", "yourcompany.atlassian.net" or a link into it
function siteHost(raw: string) {
  const s = raw.trim().toLowerCase().replace(/^https?:\/\//, "").split("/")[0]!;
  const host = s.includes(".") ? s : `${s}.atlassian.net`;
  // only Atlassian's own hosts: the key decides where the email and token are sent
  if (!/^[a-z0-9][a-z0-9-]*\.(atlassian\.net|jira\.com)$/.test(host)) throw new AppsError(`${raw} isn't a Jira Cloud site: use the address you open Jira at, like yourcompany.atlassian.net`);
  return host;
}

// The pasted line: the site, the account's email and the API token, separated by spaces, in any order.
export function parseKey(key: string): Login {
  const parts = key.trim().split(/\s+/).filter(Boolean);
  const email = parts.find((p) => p.includes("@") && !p.includes("/"));
  const site = parts.find((p) => p !== email && /atlassian\.net|jira\.com|^https?:/i.test(p));
  const token = parts.find((p) => p !== email && p !== site);
  if (parts.length !== 3 || !email || !site || !token)
    throw new AppsError("paste three things separated by spaces: your Jira site (yourcompany.atlassian.net), the email you sign in with, and an API token");
  return { site: siteHost(site), email, token };
}

const api: Api = {
  name: "Jira",
  base: "https://your-domain.atlassian.net",
  tokenHelp: "id.atlassian.com/manage-profile/security/api-tokens",
  auth: (key) => {
    const { email, token } = parseKey(key);
    // X-Atlassian-Token: uploads (attachments, avatars) are refused without it, and it does nothing elsewhere
    return { Authorization: `Basic ${Buffer.from(`${email}:${token}`).toString("base64")}`, Accept: "application/json", "X-Atlassian-Token": "no-check" };
  },
  url: (key, _base, path) => `https://${parseKey(key).site}${path}`,
  // avatars are sent as the picture itself
  upload: (file, _send, headers) => {
    headers["Content-Type"] = file.mimetype;
  },
};

// Jira wants rich text (descriptions, comments) in its document format; plain text is wrapped into one, a paragraph per blank line
export const adf = (v: unknown) =>
  typeof v !== "string"
    ? v
    : { type: "doc", version: 1, content: v.split(/\n\s*\n/).map((p) => ({ type: "paragraph", content: p ? [{ type: "text", text: p }] : [] })) };
const TEXT_FIELDS = ["description", "environment"];
const withText = (action: OwnAction, fix: (i: Record<string, any>) => Record<string, any>): OwnAction => ({ ...action, input: action.input, run: (i, key) => action.run(fix(i), key) });
const fieldsText = (i: Record<string, any>) =>
  i.fields && typeof i.fields === "object" ? { ...i, fields: { ...i.fields, ...Object.fromEntries(TEXT_FIELDS.filter((f) => typeof i.fields[f] === "string").map((f) => [f, adf(i.fields[f])])) } } : i;

const actions = await specActions(new URL("./actions.json", import.meta.url), api);
for (const name of ["create_issue", "edit_issue"]) actions[name] = withText(actions[name]!, fieldsText);
for (const name of ["add_comment", "update_comment"]) actions[name] = withText(actions[name]!, (i) => ({ ...i, body: adf(i.body) }));
for (const name of ["create_issue", "edit_issue", "add_comment", "update_comment"])
  actions[name]!.description += " Text (a description or comment body) can be plain text; Emplio turns it into Jira's rich-text format.";

// the six calls the generator can't send: a picture as the whole body, and JSON Patch documents
const PICTURE = { file: z.any().describe('The picture from the computer: {"file": "/work/logo.png"}'), x: z.number().int().optional().describe("Left edge of the square to crop, in pixels (default 0)"), y: z.number().int().optional().describe("Top edge of the square to crop (default 0)"), size: z.number().int().describe("Side of the square to crop, in pixels, e.g. the picture's width") };
const picture = (description: string, path: string, ids: z.ZodRawShape): OwnAction => ({
  description: `${description} Answers the new avatar's id; set it as the current one with the matching update call.`,
  input: z.object({ ...ids, ...PICTURE }),
  run: (i, key) => {
    if (!(i.file instanceof AppFile)) throw new AppsError('file: give the picture as {"file": "/work/logo.png"}');
    return call(api, key, { method: "POST", path, query: ["x", "y", "size"], headers: [], body: { kind: "file", field: "file" } }, i);
  },
});
const OPERATIONS = z.array(z.object({ op: z.string(), path: z.string(), value: z.any().optional() }).loose()).min(1).describe('JSON Patch steps, e.g. [{"op": "replace", "path": "/name", "value": "Q3 plan"}]');
const patch = (description: string, path: string, ids: z.ZodRawShape, query: string[] = []): OwnAction => ({
  description,
  input: z.object({ ...ids, operations: OPERATIONS }),
  run: (i, key) => call(api, key, { method: "PUT", path, query, headers: [["content_type", "Content-Type"]], body: { kind: "whole", field: "operations" } }, { ...i, content_type: "application/json-patch+json" }),
});
const PLAN = { planId: z.number().int().describe("The plan's id (get_plans lists them)") };

const hand: Record<string, OwnAction> = {
  load_issue_type_avatar: picture("Upload a picture as an issue type's icon.", "/rest/api/3/issuetype/{id}/avatar2", { id: z.string().describe("The issue type's id") }),
  load_project_avatar: picture("Upload a picture as a project's avatar.", "/rest/api/3/project/{projectIdOrKey}/avatar2", { projectIdOrKey: z.string().describe("The project's key, like SALES, or id") }),
  load_avatar: picture("Upload a picture as the avatar of a project, issue type or priority.", "/rest/api/3/universal_avatar/type/{type}/owner/{entityId}", {
    type: z.enum(["project", "issuetype", "priority"]).describe("What it's for"),
    entityId: z.string().describe("The id of that project, issue type or priority"),
  }),
  update_plan: patch("Change a plan (Jira Premium's Plans): its name, lead, scheduling, issue sources and so on.", "/rest/api/3/plans/plan/{planId}", { ...PLAN, useGroupId: z.boolean().optional().describe("Give groups by id rather than name") }, ["useGroupId"]),
  update_atlassian_team_in_plan: patch("Change how an Atlassian team works in a plan: planning style, capacity, sprint length.", "/rest/api/3/plans/plan/{planId}/team/atlassian/{atlassianTeamId}", {
    ...PLAN,
    atlassianTeamId: z.string().describe("The Atlassian team's id"),
  }),
  update_plan_only_team: patch("Change a team that exists only in a plan: name, members, planning style, capacity.", "/rest/api/3/plans/plan/{planId}/team/planonly/{planOnlyTeamId}", {
    ...PLAN,
    planOnlyTeamId: z.number().int().describe("The plan-only team's id"),
  }),
};

const ME: Send = { method: "GET", path: "/rest/api/3/myself", query: [], headers: [] };

export const jira: OwnApp = {
  app: "jira",
  name: "Jira",
  logo: "/logos/jira.svg",
  keyField: {
    label: "Site, email and API token",
    help: "Paste three things on one line, separated by spaces: 1) your Jira site, the address you open Jira at (yourcompany.atlassian.net); 2) the email you sign in to Jira with; 3) an API token. Make the token at id.atlassian.com/manage-profile/security/api-tokens → Create API token (not the one \"with scopes\"), name it Emplio, and copy it. Emplio can then do whatever your Jira account can.",
    placeholder: "yourcompany.atlassian.net you@company.com ATATT3xFfGF0...",
  },
  async check(key) {
    const { site } = parseKey(key);
    const me = (await call(api, key, ME, {})) as { displayName?: string; emailAddress?: string; accountId?: string };
    return `${me.displayName || me.emailAddress || me.accountId} (${site})`;
  },
  push: {
    events,
    triggers,
    start: (key, connection) => watch(api, key, connection),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery) => receive(delivery),
    wanted,
  },
  actions: {
    ...actions,
    ...hand,
    // more of Composio's names for calls that already have one here
    list_comments: actions.list_issue_comments!,
    search_issues: actions.search_for_issues_using_jql_get!,
    who_am_i: actions.get_current_user!,
    get_info: actions.get_server_info!,
    get_project_type: actions.get_project_type_by_key!,
    find_users2: actions.find_users_by_query!,
    list_all_projects: actions.get_projects_paginated!,
    list_assignable_users: actions.find_users_assignable_to_issues!,
    list_groups_picker: actions.get_all_groups!,
    get_group: actions.list_group_members!,
    get_project_templates: actions.gets_custom_project_template!,
    // Atlassian retired the plain delete; this one deletes too, optionally moving the version's issues elsewhere first
    delete_version: actions.delete_and_replace_version!,
  },
};
